sql.where:
published_yn = 'Y'
and completion_type = #{criteria.normalizedCompletionType}
and semester = #{criteria.normalizedSemester}
and course_area = #{criteria.normalizedCourseArea}
and faculty_user_id = #{criteria.facultyUserId}

    and (employee_no ilike concat('%', #{criteria.normalizedKeyword}, '%') or faculty_name ilike concat('%', #{criteria.normalizedKeyword}, '%'))
